// Bike facilities alongside roads, from OSM: credit a road where a bike path runs parallel to it.
//
// Used by the live builder (VersaTiles OSM tiles: separate cycleways and bicycle=yes paths only, since road
// cycleway=* tags are not in the tiles) and by the offline build (full OSM tags, which also give painted lanes).
//
// A road sample counts as "alongside" when a bike-facility segment lies within maxD metres and runs within maxAngDeg
// of the road's direction. Only sustained runs count (>= minRunM along the road), so crossings, short connectors and
// paths that merely touch the road are not credited. Bike segments come from OSM features of at least minFeatM.
// All coordinates are local metres (any planar frame).

// maxD: within this of the road centre line; wideMaxD for roads >= 5.5 m wide (multi-lane roads put a sidewalk bike path 20-30 m from the centre line)
export const BIKE_DEFAULTS = { maxD: 20, wideMaxD: 32, maxAngDeg: 25, minRunM: 60, stepM: 10, minFeatM: 30 };

// Is this OSM way a bike facility in its own right? (tags as a plain object; VersaTiles uses kind/bicycle)
export function isBikeWay(t) {
  const hw = t.highway ?? t.kind;
  if (hw === 'cycleway') return true;
  return /^(path|footway|pedestrian|bridleway|track)$/.test(hw ?? '') && /^(yes|designated|permissive)$/.test(String(t.bicycle ?? ''));
}
// Dedicated cycleway (2) or shared path (3: footway/path + bicycle=yes|designated, e.g. 自転車歩行者道 sidewalks)?
// A segregated path (segregated=yes: bike half marked off from walkers) counts as dedicated.
export function bikeWayType(t) {
  if (!isBikeWay(t)) return 0;
  return (t.highway ?? t.kind) === 'cycleway' || String(t.segregated ?? '') === 'yes' ? 2 : 3;
}
// Bike facility tagged on the road itself (full OSM tags only): 2 track (separated), 1 painted lane, 0 none.
// shared_lane / share_busway / pictograms (自転車ナビマーク) are paint in mixed traffic: no credit.
export function roadBikeTag(t) {
  let best = 0;
  for (const k of ['cycleway', 'cycleway:left', 'cycleway:right', 'cycleway:both', 'cycleway_left', 'cycleway_right', 'cycleway_both']) {
    const v = String(t[k] ?? '');
    if (/^(track|separate|opposite_track)$/.test(v)) best = Math.max(best, v === 'separate' ? 0 : 2); // 'separate' = mapped as its own way
    else if (/^(lane|opposite_lane|buffered_lane)$/.test(v)) best = Math.max(best, 1);
  }
  return best;
}

// lines: arrays of [x, y] (local metres) that are bike facilities -> segment index
// Join bike lines that meet end-to-end at a point shared by exactly two line ends (within tol metres). OSM chops a
// roadside path into short ways at every crossing and driveway (Tohachi-doro: ~260 ways over 5 km) and tiles cut it at
// tile edges, so the length filters below must see the joined path, not the pieces. Ends shared by 3+ lines
// (crossings, branches) are not joined, so short crossing stubs stay short and are still filtered out.
export function joinBikeLines(lines, tol = 3) {
  const key = (p) => `${Math.round(p[0] / tol)},${Math.round(p[1] / tol)}`;
  const ends = new Map(); // key -> [lineIndex, atStart]
  lines.forEach((l, i) => { if (l.length < 2) return; for (const [p, atStart] of [[l[0], true], [l[l.length - 1], false]]) { const k = key(p); (ends.get(k) ?? ends.set(k, []).get(k)).push([i, atStart]); } });
  const used = new Uint8Array(lines.length), out = [];
  const partner = (i, atStart) => { const l = lines[i], e = ends.get(key(atStart ? l[0] : l[l.length - 1])); return e && e.length === 2 ? e.find(([j, s]) => !(j === i && s === atStart)) : null; };
  for (let i = 0; i < lines.length; i++) {
    if (used[i] || lines[i].length < 2) continue;
    // walk back to the start of this chain of 2-way joins
    let cur = i, curStart = true, guard = 0;
    for (;;) { const pr = partner(cur, curStart); if (!pr || used[pr[0]] || pr[0] === i || ++guard > lines.length) break; cur = pr[0]; curStart = !pr[1]; }
    // cur's end `curStart` is the chain's open end; walk forward collecting
    let path = [], j = cur, fromStart = curStart;
    guard = 0;
    while (j != null && !used[j] && ++guard <= lines.length) {
      used[j] = 1;
      const l = fromStart ? lines[j] : [...lines[j]].reverse();
      path = path.length ? path.concat(l.slice(1)) : l.slice();
      const pr = partner(j, !fromStart);
      if (!pr || used[pr[0]]) break;
      j = pr[0]; fromStart = pr[1];
    }
    out.push(path);
  }
  return out;
}

export function bikeIndex(lines, opt = {}) {
  const O = { ...BIKE_DEFAULTS, ...opt }, cell = 50;
  const segs = [];
  lines = joinBikeLines(lines);
  for (const line of lines) {
    let L = 0; for (let i = 1; i < line.length; i++) L += Math.hypot(line[i][0] - line[i - 1][0], line[i][1] - line[i - 1][1]);
    if (L < O.minFeatM) continue; // crossings and tiny connectors
    for (let i = 1; i < line.length; i++) if (line[i][0] !== line[i - 1][0] || line[i][1] !== line[i - 1][1]) segs.push([line[i - 1][0], line[i - 1][1], line[i][0], line[i][1]]);
  }
  const grid = new Map();
  segs.forEach((s, i) => {
    const m = Math.max(O.maxD, O.wideMaxD);
    const x0 = Math.floor((Math.min(s[0], s[2]) - m) / cell), x1 = Math.floor((Math.max(s[0], s[2]) + m) / cell);
    const y0 = Math.floor((Math.min(s[1], s[3]) - m) / cell), y1 = Math.floor((Math.max(s[1], s[3]) + m) / cell);
    for (let gx = x0; gx <= x1; gx++) for (let gy = y0; gy <= y1; gy++) { const k = gx * 1e6 + gy; (grid.get(k) ?? grid.set(k, []).get(k)).push(i); }
  });
  const maxAng = (O.maxAngDeg * Math.PI) / 180;
  const angDiff = (a, b) => { const d = Math.abs(a - b) % Math.PI; return Math.min(d, Math.PI - d); };
  // is there a parallel bike segment near (x, y) for a road heading `ang`?
  function alongside(x, y, ang, maxD = O.maxD) {
    const list = grid.get(Math.floor(x / cell) * 1e6 + Math.floor(y / cell)); if (!list) return false;
    for (const i of list) {
      const s = segs[i], dx = s[2] - s[0], dy = s[3] - s[1], l2 = dx * dx + dy * dy;
      if (angDiff(Math.atan2(dy, dx), ang) > maxAng) continue;
      const u = Math.max(0, Math.min(1, ((x - s[0]) * dx + (y - s[1]) * dy) / l2));
      if (Math.hypot(s[0] + u * dx - x, s[1] + u * dy - y) <= maxD) return true;
    }
    return false;
  }
  return { n: segs.length, alongside, opt: O };
}

// Sample a road polyline (local metres): returns { s: Float64Array positions along the line, hit: Uint8Array } with
// runs shorter than minRunM cleared, and covered(t0, t1) = fraction of [t0, t1] (metres along) that is alongside.
// wide: the road is >= 13 m / 4 lanes (search up to opt.wideMaxD)
export function bikeAlongRoad(coords, index, wide = false) {
  const O = index.opt, S = [], H = [], maxD = wide ? O.wideMaxD : O.maxD;
  let cum = 0, next = O.stepM / 2;
  for (let i = 1; i < coords.length; i++) {
    const [ax, ay] = coords[i - 1], [bx, by] = coords[i], L = Math.hypot(bx - ax, by - ay); if (!(L > 0)) continue;
    const ang = Math.atan2(by - ay, bx - ax);
    for (; next < cum + L; next += O.stepM) {
      const d = next - cum;
      S.push(next); H.push(index.n ? (index.alongside(ax + ((bx - ax) * d) / L, ay + ((by - ay) * d) / L, ang, maxD) ? 1 : 0) : 0);
    }
    cum += L;
  }
  const s = Float64Array.from(S), hit = Uint8Array.from(H);
  for (let i = 0; i < hit.length;) { // clear short runs, but only inside the link: a run reaching either end of the link
    if (!hit[i]) { i++; continue; }  // can continue into the next one (GSI splits roads like Tohachi-doro into many
    let j = i; while (j < hit.length && hit[j]) j++; // 40-60 m links, which a whole-link 60 m minimum always cleared)
    if ((j - i) * O.stepM < O.minRunM && i > 0 && j < hit.length) hit.fill(0, i, j);
    i = j;
  }
  const covered = (t0, t1) => {
    let a = 0, b = 0;
    for (let k = 0; k < s.length; k++) { if (s[k] < t0 || s[k] >= t1) continue; a++; b += hit[k]; }
    return a ? b / a : 0;
  };
  return { s, hit, covered, any: hit.some((v) => v) };
}

// ---- continuity: fill short gaps in the "separated path alongside" credit along a road --------------------------
// Detection is per 20 m piece, so a continuous roadside path still leaves uncredited pieces where OSM splits it at
// intersections (short crossing segments), at wide junction mouths, or where the path briefly leaves the 20-32 m
// band. Tohachi-doro (Mitaka) measured 25-86% credited per 200 m although the path runs its whole length.
// Roads are followed through junctions where a chain continues straight (same class, bearings within maxTurnDeg of
// opposite); along each such run an uncredited span of at most maxGapM is credited when the road within windowM on
// both sides of it is at least minShare credited. Works on the typed graph (web/CONTRACT.md §2) in place.
export const GAP_DEFAULTS = { maxGapM: 150, windowM: 250, minShare: 0.6, maxTurnDeg: 30 };
export function fillBikeGaps(g, opt = {}) {
  const O = { ...GAP_DEFAULTS, ...opt };
  if (!g.atomBike || !g.nChains) return { filledM: 0 };
  const kx = Math.cos(((g.nodeLat?.[0] ?? 36) * Math.PI) / 180) * 111320, ky = 110574;
  const nC = g.nChains;
  const cls = (c) => g.atomRc[g.atomStart[c]];
  // bearing (radians) leaving node `end` (0 = chainA side, 1 = chainB side) into the chain
  const bearing = (c, end) => {
    const s = g.coordStart[c], e = g.coordStart[c + 1] - 1;
    const [i0, i1] = end === 0 ? [s, Math.min(s + 1, e)] : [e, Math.max(e - 1, s)];
    return Math.atan2((g.coordLat[i1] - g.coordLat[i0]) * ky, (g.coordLon[i1] - g.coordLon[i0]) * kx);
  };
  // incident chain ends per node
  const ends = new Map();
  for (let c = 0; c < nC; c++) {
    if (cls(c) > 9 || g.chainA[c] === g.chainB[c]) continue;
    for (const end of [0, 1]) { const n = end === 0 ? g.chainA[c] : g.chainB[c]; (ends.get(n) ?? ends.set(n, []).get(n)).push({ c, end, b: bearing(c, end) }); }
  }
  // straight continuation pairs (mutual best), per chain end: next[2c+end] = 2c'+end' of the continuing chain's end at this node
  const next = new Int32Array(2 * nC).fill(-1), maxTurn = (O.maxTurnDeg * Math.PI) / 180;
  for (const list of ends.values()) {
    const cand = [];
    for (let p = 0; p < list.length; p++) for (let q = p + 1; q < list.length; q++) {
      const A = list[p], B = list[q];
      if (A.c === B.c || cls(A.c) !== cls(B.c)) continue;
      let d = Math.abs(A.b - B.b) % (2 * Math.PI); if (d > Math.PI) d = 2 * Math.PI - d; // angle between the two outgoing bearings
      const turn = Math.PI - d; // 0 = perfectly straight through
      if (turn <= maxTurn) cand.push([turn, A, B]);
    }
    cand.sort((x, y) => x[0] - y[0]);
    for (const [, A, B] of cand) { const ka = 2 * A.c + A.end, kb = 2 * B.c + B.end; if (next[ka] < 0 && next[kb] < 0) { next[ka] = kb; next[kb] = ka; } }
  }
  // walk runs: start at a chain end with no continuation (or anywhere on a pure loop), then follow chains through
  const seen = new Uint8Array(nC);
  let filledM = 0;
  const walk = (c0, enterEnd) => {
    const atoms = []; // [atomIndex] in travel order
    let c = c0, end = enterEnd;
    while (c >= 0 && !seen[c]) {
      seen[c] = 1;
      const a0 = g.atomStart[c], a1 = g.atomStart[c + 1];
      if (end === 0) for (let i = a0; i < a1; i++) atoms.push(i); else for (let i = a1 - 1; i >= a0; i--) atoms.push(i);
      const exitKey = 2 * c + (1 - end), nk = next[exitKey];
      if (nk < 0) break;
      c = nk >> 1; end = nk & 1;
    }
    if (atoms.length < 3) return;
    const L = atoms.map((i) => g.atomLen[i]), cum = [0];
    for (const l of L) cum.push(cum[cum.length - 1] + l);
    const cred = atoms.map((i) => g.atomBike[i] === 2 || g.atomBike[i] === 3); // dedicated cycleway or shared sidewalk
    // credited length prefix sums for window shares
    const cc = [0]; atoms.forEach((_, k) => cc.push(cc[k] + (cred[k] ? L[k] : 0)));
    const shareIn = (from, to) => { // metres [from, to) along the run
      from = Math.max(0, from); to = Math.min(cum[cum.length - 1], to); if (to <= from) return 0;
      const idx = (m) => { let lo = 0, hi = cum.length - 1; while (lo < hi) { const mid = (lo + hi + 1) >> 1; if (cum[mid] <= m) lo = mid; else hi = mid - 1; } return lo; };
      const kf = idx(from), kt = idx(to);
      let s = cc[kt] - cc[kf]; // whole atoms from kf .. kt-1 (approx at the ends; fine for a share)
      return s / (cum[kt] - cum[kf] || 1);
    };
    for (let k = 0; k < atoms.length; ) {
      if (cred[k]) { k++; continue; }
      let j = k; while (j < atoms.length && !cred[j]) j++;
      const gapStart = cum[k], gapEnd = cum[j], gapLen = gapEnd - gapStart;
      if (k > 0 && j < atoms.length && gapLen <= O.maxGapM &&
          shareIn(gapStart - O.windowM, gapStart) >= O.minShare && shareIn(gapEnd, gapEnd + O.windowM) >= O.minShare) {
        const fillV = g.atomBike[atoms[k - 1]] === 3 && g.atomBike[atoms[j]] === 3 ? 3 : 2; // shared only if both sides are shared
        for (let q = k; q < j; q++) { if (g.atomRc[atoms[q]] <= 9) { g.atomBike[atoms[q]] = fillV; filledM += L[q]; } }
      }
      k = j;
    }
  };
  for (let c = 0; c < nC; c++) {
    if (seen[c] || cls(c) > 9) continue;
    if (next[2 * c] < 0) walk(c, 0); else if (next[2 * c + 1] < 0) walk(c, 1);
  }
  for (let c = 0; c < nC; c++) if (!seen[c] && cls(c) <= 9) walk(c, 0); // loops
  return { filledM };
}
